"use strict";
window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["school_mathematics_en"]=window.LC_CHUNKS["school_mathematics_en"]||{};window.LC_CHUNKS["school_mathematics_en"][6]={"school_mathematics_en:M6-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M6-L1 – Matrix arithmetic and Gaussian elimination<\/h1>\n<p><strong>Course area:<\/strong> M6 – Matrices and transition models<\/p>\n<p><strong>Level:<\/strong> Upper secondary education · elective\nextension<\/p>\n<p><strong>Prior knowledge:<\/strong> <a\nhref=\"index.html?course=school_mathematics&amp;module=M1&amp;lesson=L9&amp;syslang=en&amp;doclang=en&amp;theme=light\">M1-L9<\/a>; <a\nhref=\"index.html?course=school_mathematics&amp;module=M2&amp;lesson=L13&amp;syslang=en&amp;doclang=en&amp;theme=light\">M2-L13<\/a><\/p>\n<p><strong>Context:<\/strong> Elective extension informed by Bavaria’s\nLehrplanPLUS M12; not a nationwide requirement.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Learning objectives<\/h2>\n<p>You will read matrix dimensions, add and multiply matrices, solve\nlinear systems using reversible row operations, distinguish unique,\ninfinitely many and absent solutions, and verify an inverse by\nmultiplication.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Matrices as ordered data<\/h2>\n<p>A matrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>a<\/mi><mrow><mi>i<\/mi><mi>j<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">A=(a_{ij})<\/annotation><\/semantics><\/math>\nwith\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>m<\/mi><annotation encoding=\"application/x-tex\">m<\/annotation><\/semantics><\/math>\nrows and\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\ncolumns has size\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>×<\/mo><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">m\\times n<\/annotation><\/semantics><\/math>.\nThe first index identifies the row and the second the column. At a\nschool kiosk, two rows might represent two days and three columns three\nproducts. In<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>4<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>5<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">A=\\begin{pmatrix}4&amp;2&amp;1\\\\3&amp;0&amp;5\\end{pmatrix}<\/annotation><\/semantics><\/math><\/p>\n<p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a<\/mi><mn>23<\/mn><\/msub><mo>=<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a_{23}=5<\/annotation><\/semantics><\/math>\nrepresents five units of the third product on the second day. Matrices\nof equal size are added entry by entry; scalar multiplication scales\nevery entry. Thus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>A<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2A<\/annotation><\/semantics><\/math>\nrepresents doubled quantities, while\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>+<\/mo><mi>A<\/mi><\/mrow><annotation encoding=\"application/x-tex\">A+A<\/annotation><\/semantics><\/math>\nretains the same dimensions. Matrices of different sizes cannot be\nadded.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Matrix products and order<\/h2>\n<p>For an\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>×<\/mo><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">m\\times n<\/annotation><\/semantics><\/math>\nmatrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\nand an\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>×<\/mo><mi>p<\/mi><\/mrow><annotation encoding=\"application/x-tex\">n\\times p<\/annotation><\/semantics><\/math>\nmatrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>B<\/mi><annotation encoding=\"application/x-tex\">B<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>A<\/mi><mi>B<\/mi><msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mrow><mi>i<\/mi><mi>j<\/mi><\/mrow><\/msub><mo>=<\/mo><msubsup><mo>∑<\/mo><mrow><mi>k<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><mi>n<\/mi><\/msubsup><msub><mi>a<\/mi><mrow><mi>i<\/mi><mi>k<\/mi><\/mrow><\/msub><msub><mi>b<\/mi><mrow><mi>k<\/mi><mi>j<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">(AB)_{ij}=\\sum_{k=1}^n a_{ik}b_{kj}<\/annotation><\/semantics><\/math>.\nThe inner dimensions agree; the product has size\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>×<\/mo><mi>p<\/mi><\/mrow><annotation encoding=\"application/x-tex\">m\\times p<\/annotation><\/semantics><\/math>.\nWith the price vector\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>3<\/mn><mo>,<\/mo><mn>4<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">v=(2,3,4)^T<\/annotation><\/semantics><\/math>\nin euros, the kiosk receives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mi>v<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>18<\/mn><mo>,<\/mo><mn>26<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">Av=(18,26)^T<\/annotation><\/semantics><\/math>\neuros. Each entry comes from one row and one column, not from\nmultiplying corresponding entries.<\/p>\n<p>Even for square matrices, order matters. For<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>D<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">C=\\begin{pmatrix}1&amp;1\\\\0&amp;1\\end{pmatrix},\\qquad D=\\begin{pmatrix}2&amp;0\\\\0&amp;3\\end{pmatrix}<\/annotation><\/semantics><\/math><\/p>\n<p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C<\/mi><mi>D<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">CD=\\begin{pmatrix}2&amp;3\\\\0&amp;3\\end{pmatrix}<\/annotation><\/semantics><\/math>\nbut\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mi>C<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">DC=\\begin{pmatrix}2&amp;2\\\\0&amp;3\\end{pmatrix}<\/annotation><\/semantics><\/math>.\nMatrix multiplication is associative but generally not commutative. With\ncolumn vectors,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C<\/mi><mi>D<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">CDx<\/annotation><\/semantics><\/math>\nmeans apply\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>D<\/mi><annotation encoding=\"application/x-tex\">D<\/annotation><\/semantics><\/math>\nfirst, then\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>C<\/mi><annotation encoding=\"application/x-tex\">C<\/annotation><\/semantics><\/math>.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gaussian elimination<\/h2>\n<p>Write a linear system as an augmented matrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>A<\/mi><mo>∣<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[A\\mid b]<\/annotation><\/semantics><\/math>.\nAllowed operations are swapping rows, multiplying a row by a nonzero\nnumber, and adding a multiple of another row. Each operation is\nreversible and therefore preserves the solution set. The pivot is the\nleading entry used to eliminate entries beneath it. If a proposed pivot\nis zero, find a suitable entry beneath it and swap rows; if none exists,\nmove to the next column.<\/p>\n<p>Example:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>x<\/mi><mo>+<\/mo><mi>y<\/mi><mo>=<\/mo><mn>7<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2x+y=7<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>−<\/mo><mi>y<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x-y=2<\/annotation><\/semantics><\/math>.\nFirst swap rows, then subtract twice the first row from the second:<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>7<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mo>→<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>7<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mo>→<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\left(\\begin{array}{cc|c}2&amp;1&amp;7\\\\1&amp;-1&amp;2\\end{array}\\right)\\to\\left(\\begin{array}{cc|c}1&amp;-1&amp;2\\\\2&amp;1&amp;7\\end{array}\\right)\\to\\left(\\begin{array}{cc|c}1&amp;-1&amp;2\\\\0&amp;3&amp;3\\end{array}\\right).<\/annotation><\/semantics><\/math><\/p>\n<p>Back substitution gives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y=1<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=3<\/annotation><\/semantics><\/math>.\nChecking gives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>6<\/mn><mo>+<\/mo><mn>1<\/mn><mo>=<\/mo><mn>7<\/mn><\/mrow><annotation encoding=\"application/x-tex\">6+1=7<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mo>−<\/mo><mn>1<\/mn><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3-1=2<\/annotation><\/semantics><\/math>.\nA row\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mspace width=\"0.278em\"><\/mspace><mn>0<\/mn><mo>∣<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0\\;0\\mid1]<\/annotation><\/semantics><\/math>\nindicates a contradiction. A zero row instead indicates a redundant\nequation. If a consistent system has a variable without a pivot, that\nvariable can be freely chosen; there are infinitely many real\nsolutions.<\/p>\n<figure>\n<img src=\"../learning-courses-school-mathematics-en/media/img/S_MAT_039_EN.svg\"\nalt=\"Three augmented matrices: row swap, elimination of 2 below the pivot, then back substitution.\" />\n<figcaption>Figure: Gaussian elimination with two reversible row\noperations.<\/figcaption>\n<\/figure>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Identity matrix and inverse<\/h2>\n<p>The identity matrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>I<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">I_n<\/annotation><\/semantics><\/math>\nhas ones on the main diagonal and zeros elsewhere. A square matrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\nis invertible if a matrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>A<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><annotation encoding=\"application/x-tex\">A^{-1}<\/annotation><\/semantics><\/math>\nexists with\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><msup><mi>A<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mo>=<\/mo><msup><mi>A<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mi>A<\/mi><mo>=<\/mo><msub><mi>I<\/mi><mi>n<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">AA^{-1}=A^{-1}A=I_n<\/annotation><\/semantics><\/math>.\nFor a\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo>×<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2\\times2<\/annotation><\/semantics><\/math>\nmatrix,<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mi>a<\/mi><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mi>b<\/mi><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mi>c<\/mi><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mi>d<\/mi><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mo>=<\/mo><mfrac><mn>1<\/mn><mrow><mi>a<\/mi><mi>d<\/mi><mo>−<\/mo><mi>b<\/mi><mi>c<\/mi><\/mrow><\/mfrac><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mi>d<\/mi><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mi>b<\/mi><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mi>c<\/mi><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mi>a<\/mi><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\begin{pmatrix}a&amp;b\\\\c&amp;d\\end{pmatrix}^{-1}=\\frac1{ad-bc}\\begin{pmatrix}d&amp;-b\\\\-c&amp;a\\end{pmatrix}<\/annotation><\/semantics><\/math><\/p>\n<p>provided\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mi>d<\/mi><mo>−<\/mo><mi>b<\/mi><mi>c<\/mi><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">ad-bc\\ne0<\/annotation><\/semantics><\/math>.\nFor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">E=\\begin{pmatrix}2&amp;1\\\\1&amp;1\\end{pmatrix}<\/annotation><\/semantics><\/math>,\nthe inverse is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>E<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mn>1<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">E^{-1}=\\begin{pmatrix}1&amp;-1\\\\-1&amp;2\\end{pmatrix}<\/annotation><\/semantics><\/math>.\nTheir product is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>I<\/mi><mn>2<\/mn><\/msub><annotation encoding=\"application/x-tex\">I_2<\/annotation><\/semantics><\/math>.\nFor larger square matrices, row operations can transform\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>A<\/mi><mo>∣<\/mo><mi>I<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[A\\mid I]<\/annotation><\/semantics><\/math>\ninto\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>I<\/mi><mo>∣<\/mo><msup><mi>A<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[I\\mid A^{-1}]<\/annotation><\/semantics><\/math>,\nprovided the identity can actually be obtained on the left. If\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\nis invertible,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mi>x<\/mi><mo>=<\/mo><mi>b<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Ax=b<\/annotation><\/semantics><\/math>\nhas the unique solution\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><msup><mi>A<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mi>b<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x=A^{-1}b<\/annotation><\/semantics><\/math>.\nIf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\nis not invertible, solvability must be checked separately.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Modelling and checking<\/h2>\n<p>A theatre sells 30 tickets at 8 or 12 euros and receives 300 euros.\nWith\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x<\/mi><annotation encoding=\"application/x-tex\">x<\/annotation><\/semantics><\/math>\ncheaper and\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>y<\/mi><annotation encoding=\"application/x-tex\">y<\/annotation><\/semantics><\/math>\nmore expensive tickets,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>+<\/mo><mi>y<\/mi><mo>=<\/mo><mn>30<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x+y=30<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>8<\/mn><mi>x<\/mi><mo>+<\/mo><mn>12<\/mn><mi>y<\/mi><mo>=<\/mo><mn>300<\/mn><\/mrow><annotation encoding=\"application/x-tex\">8x+12y=300<\/annotation><\/semantics><\/math>.\nSubtracting eight times the first equation from the second gives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4<\/mn><mi>y<\/mi><mo>=<\/mo><mn>60<\/mn><\/mrow><annotation encoding=\"application/x-tex\">4y=60<\/annotation><\/semantics><\/math>,\nso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mn>15<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y=15<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>15<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=15<\/annotation><\/semantics><\/math>.\nThe model also requires nonnegative integers. A mathematical solution\nsuch as\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mn>15.25<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y=15.25<\/annotation><\/semantics><\/math>\nwould not be a valid ticket count. With rounded measurements, small\npivots can amplify rounding errors; exact fractions in hand calculations\nand substitution into the original system are therefore useful.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Self-check<\/h2>\n<h3 id=\"exercises\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Exercises<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Find the size of\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\nfrom S2 and\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>a<\/mi><mn>12<\/mn><\/msub><annotation encoding=\"application/x-tex\">a_{12}<\/annotation><\/semantics><\/math>,\nand calculate\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mi>v<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Av<\/annotation><\/semantics><\/math>\nfor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mo>,<\/mo><mn>3<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">v=(1,2,3)^T<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Calculate\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C<\/mi><mi>D<\/mi><\/mrow><annotation encoding=\"application/x-tex\">CD<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mi>C<\/mi><\/mrow><annotation encoding=\"application/x-tex\">DC<\/annotation><\/semantics><\/math>\nfrom S3 and explain the different order of transformations.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Solve\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>+<\/mo><mn>2<\/mn><mi>y<\/mi><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x+2y=8<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mi>x<\/mi><mo>−<\/mo><mi>y<\/mi><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3x-y=3<\/annotation><\/semantics><\/math>\nby elimination and verify your result.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Investigate the systems\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>+<\/mo><mi>y<\/mi><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x+y=4<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>x<\/mi><mo>+<\/mo><mn>2<\/mn><mi>y<\/mi><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2x+2y=8<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>x<\/mi><mo>+<\/mo><mn>2<\/mn><mi>y<\/mi><mo>=<\/mo><mn>9<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2x+2y=9<\/annotation><\/semantics><\/math>\n(each with the same first equation).<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Find the inverse of\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">F=\\begin{pmatrix}3&amp;2\\\\1&amp;1\\end{pmatrix}<\/annotation><\/semantics><\/math>\nand solve\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F<\/mi><mi>z<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>7<\/mn><mo>,<\/mo><mn>3<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">Fz=(7,3)^T<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S7\"><summary>Show solutions<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo>×<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2\\times3<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a<\/mi><mn>12<\/mn><\/msub><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a_{12}=2<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mi>v<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>11<\/mn><mo>,<\/mo><mn>18<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">Av=(11,18)^T<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C<\/mi><mi>D<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">CD=\\begin{pmatrix}2&amp;3\\\\0&amp;3\\end{pmatrix}<\/annotation><\/semantics><\/math>;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mi>C<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">DC=\\begin{pmatrix}2&amp;2\\\\0&amp;3\\end{pmatrix}<\/annotation><\/semantics><\/math>.\nWith column vectors, the right-hand factor acts first.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Subtracting three times the first row from the second gives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>7<\/mn><mi>y<\/mi><mo>=<\/mo><mi>−<\/mi><mn>21<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-7y=-21<\/annotation><\/semantics><\/math>,\nso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y=3<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=2<\/annotation><\/semantics><\/math>.\nCheck:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo>+<\/mo><mn>6<\/mn><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2+6=8<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>6<\/mn><mo>−<\/mo><mn>3<\/mn><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">6-3=3<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">The first case gives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0=0<\/annotation><\/semantics><\/math>;\nall\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mo>−<\/mo><mi>t<\/mi><mo>,<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(x,y)=(4-t,t)<\/annotation><\/semantics><\/math>\nwith\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>∈<\/mo><mi mathvariant=\"double-struck\">ℝ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t\\in\\mathbb R<\/annotation><\/semantics><\/math>\nsolve the system. The second gives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0=1<\/annotation><\/semantics><\/math>,\nso there is no solution.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">det<\/mi><mo>&#8289;<\/mo><\/mrow><mi>F<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\det F=1<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>F<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mn>2<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">F^{-1}=\\begin{pmatrix}1&amp;-2\\\\-1&amp;3\\end{pmatrix}<\/annotation><\/semantics><\/math>.\nHence\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>z<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">z=(1,2)^T<\/annotation><\/semantics><\/math>;\ncheck:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mo>+<\/mo><mn>4<\/mn><mo>=<\/mo><mn>7<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3+4=7<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>+<\/mo><mn>2<\/mn><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1+2=3<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S8\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Sources<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://openstax.org/books/college-algebra-2e/pages/7-5-matrices-and-matrix-operations\">OpenStax\n– College Algebra 2e, 7.5 Matrices and Matrix Operations<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · matrix\noperations · Last accessed: 2026-11-24 · Content verified:\n2026-11-24<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://openstax.org/books/college-algebra-2e/pages/7-6-solving-systems-with-gaussian-elimination\">OpenStax\n– College Algebra 2e, 7.6 Solving Systems with Gaussian Elimination<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a>\n· row operations · Last accessed: 2026-11-24 · Content verified:\n2026-11-24<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://openstax.org/books/college-algebra/pages/7-7-solving-systems-with-inverses\">OpenStax\n– College Algebra, 7.7 Solving Systems with Inverses<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · inverses and\nsolvability · Last accessed: 2026-11-24 · Content verified:\n2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","school_mathematics_en:M6-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M6-L2 – Transition matrices and absorbing states<\/h1>\n<p><strong>Course area:<\/strong> M6 – Matrices and transition models<\/p>\n<p><strong>Level:<\/strong> Upper secondary education · elective\nextension<\/p>\n<p><strong>Prior knowledge:<\/strong> <a\nhref=\"index.html?course=school_mathematics&amp;module=M6&amp;lesson=L1&amp;syslang=en&amp;doclang=en&amp;theme=light\">M6-L1<\/a>; <a\nhref=\"index.html?course=school_mathematics&amp;module=M2&amp;lesson=L15&amp;syslang=en&amp;doclang=en&amp;theme=light\">M2-L15<\/a><\/p>\n<p><strong>Context:<\/strong> Elective extension informed by Bavaria’s\nLehrplanPLUS M12; not a nationwide requirement.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Learning objectives<\/h2>\n<p>You will translate a state diagram into a transition matrix,\ncalculate distributions after multiple steps, and check invariant\ndistributions. For a model with absorbing states, you will determine the\nprobability of a final outcome and distinguish model assumptions from\nmeasured data.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>States and transition matrices<\/h2>\n<p>A discrete-time process is observed at times\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mo>,<\/mo><mi>…<\/mi><\/mrow><annotation encoding=\"application/x-tex\">n=0,1,2,\\ldots<\/annotation><\/semantics><\/math>.\nA time-homogeneous Markov chain assumes that the conditional\ndistribution of the next state depends only on the current state and\nthat transition probabilities remain constant over time. We use row\nvectors:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>p<\/mi><mrow><mi>i<\/mi><mi>j<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">p_{ij}<\/annotation><\/semantics><\/math>\nis the probability of moving from state\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>i<\/mi><annotation encoding=\"application/x-tex\">i<\/annotation><\/semantics><\/math>\nto state\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>j<\/mi><annotation encoding=\"application/x-tex\">j<\/annotation><\/semantics><\/math>.\nEach row of\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>P<\/mi><annotation encoding=\"application/x-tex\">P<\/annotation><\/semantics><\/math>\nsums to one and all entries are nonnegative. Under the alternative\ncolumn-vector convention, the matrix would be transposed.<\/p>\n<p>A simplified bicycle rental model distinguishes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\n(bike at station A) and\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>B<\/mi><annotation encoding=\"application/x-tex\">B<\/annotation><\/semantics><\/math>\n(bike at station B). Suppose the hypothetical daily transitions are<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><mi>/<\/mi><mn>4<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P=\\begin{pmatrix}3/4&amp;1/4\\\\1/2&amp;1/2\\end{pmatrix}.<\/annotation><\/semantics><\/math><\/p>\n<p>A bike at A remains there with probability\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3/4<\/annotation><\/semantics><\/math>,\nwhereas a bike at B moves to A with probability\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>.\nThese invented numbers do not describe a measured rental operation.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Distributions and multiple steps<\/h2>\n<p>A distribution\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>a<\/mi><mi>n<\/mi><\/msub><mo>,<\/mo><msub><mi>b<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">v_n=(a_n,b_n)<\/annotation><\/semantics><\/math>\ncontains the probabilities of the two states;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><msub><mi>b<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a_n+b_n=1<\/annotation><\/semantics><\/math>.\nBy the law of total probability, the next step is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>=<\/mo><msub><mi>v<\/mi><mi>n<\/mi><\/msub><mi>P<\/mi><\/mrow><annotation encoding=\"application/x-tex\">v_{n+1}=v_nP<\/annotation><\/semantics><\/math>.\nFor example, a bike starts at A with certainty, so\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">v_0=(1,0)<\/annotation><\/semantics><\/math>.\nThen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>3<\/mn><mi>/<\/mi><mn>4<\/mn><mo>,<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">v_1=(3/4,1/4)<\/annotation><\/semantics><\/math>\nand<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><msub><mi>v<\/mi><mn>1<\/mn><\/msub><mi>P<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>9<\/mn><mi>/<\/mi><mn>16<\/mn><mo>+<\/mo><mn>1<\/mn><mi>/<\/mi><mn>8<\/mn><mo>,<\/mo><mn>3<\/mn><mi>/<\/mi><mn>16<\/mn><mo>+<\/mo><mn>1<\/mn><mi>/<\/mi><mn>8<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>11<\/mn><mi>/<\/mi><mn>16<\/mn><mo>,<\/mo><mn>5<\/mn><mi>/<\/mi><mn>16<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">v_2=v_1P=(9/16+1/8,3/16+1/8)=(11/16,5/16).<\/annotation><\/semantics><\/math><\/p>\n<p>In general,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><msub><mi>v<\/mi><mn>0<\/mn><\/msub><msup><mi>P<\/mi><mi>n<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">v_n=v_0P^n<\/annotation><\/semantics><\/math>,\nwhere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>P<\/mi><mn>0<\/mn><\/msup><mo>=<\/mo><mi>I<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P^0=I<\/annotation><\/semantics><\/math>.\nThe entries of\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>P<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">P^2<\/annotation><\/semantics><\/math>\nare two-step transition probabilities. The probability of being at A\nafter two days, starting at A, comes from two disjoint paths A–A–A and\nA–B–A. The total probability remains one because every row of\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>P<\/mi><annotation encoding=\"application/x-tex\">P<\/annotation><\/semantics><\/math>\nsums to one.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Invariant distribution and limiting behaviour<\/h2>\n<p>An invariant distribution\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>π<\/mi><annotation encoding=\"application/x-tex\">\\pi<\/annotation><\/semantics><\/math>\nsatisfies\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>π<\/mi><mi>P<\/mi><mo>=<\/mo><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\pi P=\\pi<\/annotation><\/semantics><\/math>,\nhas nonnegative entries and sums to one. For\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>π<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>,<\/mo><mn>1<\/mn><mo>−<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\pi=(a,1-a)<\/annotation><\/semantics><\/math>,\nthe first component gives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>3<\/mn><mi>a<\/mi><mi>/<\/mi><mn>4<\/mn><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a=3a/4+(1-a)/2<\/annotation><\/semantics><\/math>,\nso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a=2/3<\/annotation><\/semantics><\/math>.\nHence\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>π<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><mo>,<\/mo><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\pi=(2/3,1/3)<\/annotation><\/semantics><\/math>.\nIn the bicycle model,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>+<\/mo><msub><mi>a<\/mi><mi>n<\/mi><\/msub><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a_{n+1}=1/2+a_n/4<\/annotation><\/semantics><\/math>,\nso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>−<\/mo><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>a<\/mi><mi>n<\/mi><\/msub><mo>−<\/mo><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a_{n+1}-2/3=(a_n-2/3)/4<\/annotation><\/semantics><\/math>.\nThus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>a<\/mi><mn>0<\/mn><\/msub><mo>−<\/mo><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mn>4<\/mn><mrow><mi>−<\/mi><mi>n<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">a_n=2/3+(a_0-2/3)4^{-n}<\/annotation><\/semantics><\/math>:\nthe distribution approaches the invariant distribution regardless of the\nstarting distribution.<\/p>\n<p>The existence of an invariant distribution alone does not guarantee\nconvergence. For\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">P=\\begin{pmatrix}0&amp;1\\\\1&amp;0\\end{pmatrix}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>,<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1/2,1/2)<\/annotation><\/semantics><\/math>\nis stationary, whereas the start\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1,0)<\/annotation><\/semantics><\/math>\nalternates between\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1,0)<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0,1)<\/annotation><\/semantics><\/math>.\nMultiple invariant distributions can also exist, for example for the\nidentity matrix.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Absorbing states<\/h2>\n<p>A state is absorbing if, once entered, it is retained with\nprobability one. A simplified inspection process for an item has states\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>W<\/mi><annotation encoding=\"application/x-tex\">W<\/annotation><\/semantics><\/math>\n(waiting for a decision),\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>G<\/mi><annotation encoding=\"application/x-tex\">G<\/annotation><\/semantics><\/math>\n(approved) and\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>R<\/mi><annotation encoding=\"application/x-tex\">R<\/annotation><\/semantics><\/math>\n(rejected). In each inspection round the item remains in W with\nprobability\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>,\nis approved with probability\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/3<\/annotation><\/semantics><\/math>\nand rejected with probability\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/6<\/annotation><\/semantics><\/math>.\nG and R are final. In the order W, G, R, the matrix is<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><mi>/<\/mi><mn>6<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Q=\\begin{pmatrix}1/2&amp;1/3&amp;1/6\\\\0&amp;1&amp;0\\\\0&amp;0&amp;1\\end{pmatrix}.<\/annotation><\/semantics><\/math><\/p>\n<figure>\n<img src=\"../learning-courses-school-mathematics-en/media/img/S_MAT_040_EN.svg\"\nalt=\"W leads to G with 1/3, to R with 1/6 and back to W with 1/2. G and R have self-loops of probability 1.\" />\n<figcaption>Figure: State diagram of the inspection model; G and R are\nabsorbing.<\/figcaption>\n<\/figure>\n<p>The probability of still waiting after\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nsteps is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mn>2<\/mn><mrow><mi>−<\/mi><mi>n<\/mi><\/mrow><\/msup><annotation encoding=\"application/x-tex\">2^{-n}<\/annotation><\/semantics><\/math>.\nIt tends to zero, so a decision is eventually reached with probability\none. If\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>h<\/mi><annotation encoding=\"application/x-tex\">h<\/annotation><\/semantics><\/math>\nis the probability of eventual approval starting at W, conditioning on\nthe first step gives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><mo>+<\/mo><mi>h<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h=1/3+h/2<\/annotation><\/semantics><\/math>.\nRejection contributes zero and approval contributes one. Hence\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h=2/3<\/annotation><\/semantics><\/math>\nand the eventual rejection probability is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/3<\/annotation><\/semantics><\/math>.\nAfter exactly\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nrounds, the probability of approval is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><msup><mn>2<\/mn><mrow><mi>−<\/mi><mi>n<\/mi><\/mrow><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(2/3)(1-2^{-n})<\/annotation><\/semantics><\/math>,\nbecause each additional round transfers one third of the remaining\nwaiting mass to G.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Application and limitations<\/h2>\n<p>To estimate transitions from observations, divide the number of\ntransitions to a particular destination by the total number observed\nfrom the corresponding starting state. Without observations, that row\ncannot be estimated. Use separate observation periods to test whether\nthe probabilities are stable. If weather or day of the week affects\nbicycle movements, for example, a model with two constant states may be\ninadequate. More states or time-dependent matrices may then be useful.\nMoreover, absorption is not guaranteed merely by the existence of an\nabsorbing state: it must also be reachable from other states; otherwise\nprobability mass may remain outside indefinitely.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Self-check<\/h2>\n<h3 id=\"exercises\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Exercises<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Check whether\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><mi>/<\/mi><mn>4<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\begin{pmatrix}1/3&amp;2/3\\\\1/4&amp;3/4\\end{pmatrix}<\/annotation><\/semantics><\/math>\nis a transition matrix under the row convention. Calculate the\ndistribution after one step from state 2.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Calculate\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>P<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">P^2<\/annotation><\/semantics><\/math>\nfor the bicycle model in S2 and the distribution after two days starting\nat B.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Solve the invariant-distribution equation for the matrix in exercise\n1.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">For the inspection model, calculate the distribution after two\nrounds starting at W.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Change the first row of the inspection model to\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><mo>,<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><mo>,<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1/4,1/4,1/2)<\/annotation><\/semantics><\/math>.\nFind the eventual approval probability and explain why a decision is\nreached with probability one.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S7\"><summary>Show solutions<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Yes, the rows sum to one and all entries are nonnegative. The\ndistribution is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><mo>,<\/mo><mn>3<\/mn><mi>/<\/mi><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1/4,3/4)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>P<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>11<\/mn><mi>/<\/mi><mn>16<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>5<\/mn><mi>/<\/mi><mn>16<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>5<\/mn><mi>/<\/mi><mn>8<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><mi>/<\/mi><mn>8<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">P^2=\\begin{pmatrix}11/16&amp;5/16\\\\5/8&amp;3/8\\end{pmatrix}<\/annotation><\/semantics><\/math>;\nstarting at B gives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>5<\/mn><mi>/<\/mi><mn>8<\/mn><mo>,<\/mo><mn>3<\/mn><mi>/<\/mi><mn>8<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(5/8,3/8)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mi>a<\/mi><mi>/<\/mi><mn>3<\/mn><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a=a/3+(1-a)/4<\/annotation><\/semantics><\/math>,\nso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>11<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a=3/11<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>π<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>3<\/mn><mi>/<\/mi><mn>11<\/mn><mo>,<\/mo><mn>8<\/mn><mi>/<\/mi><mn>11<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\pi=(3/11,8/11)<\/annotation><\/semantics><\/math>;\nsubstitution confirms\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>π<\/mi><mi>P<\/mi><mo>=<\/mo><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\pi P=\\pi<\/annotation><\/semantics><\/math>\nfor the matrix in the exercise.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><mo>,<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>,<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1/4,1/2,1/4)<\/annotation><\/semantics><\/math>,\nsince after round 1 the distribution is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>,<\/mo><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><mo>,<\/mo><mn>1<\/mn><mi>/<\/mi><mn>6<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1/2,1/3,1/6)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><mo>+<\/mo><mi>h<\/mi><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h=1/4+h/4<\/annotation><\/semantics><\/math>,\nso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h=1/3<\/annotation><\/semantics><\/math>.\nThe waiting mass\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>n<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">(1/4)^n<\/annotation><\/semantics><\/math>\ntends to zero; eventual rejection has probability\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2/3<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S8\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Sources<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://adityam.github.io/probability-and-random-signals/markov-chains.html\">Aditya\nMahajan – Probability and Random Signals II, 11 Markov chains<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> ·\ntransition matrices, distributions, invariant distributions · Last\naccessed: 2026-11-24 · Content verified: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>"};
